import json,subprocess,shutil,platform
names=['python3','gcc','make','git','strace']
d={'platform':platform.platform(),'tools':{}}
for name in names:
 path=shutil.which(name)
 if path:
  p=subprocess.run([path,'--version'],capture_output=True,text=True)
  d['tools'][name]={'path':path,'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
 else:d['tools'][name]={'path':None,'available':False,'exit_code':127}
print(json.dumps(d,indent=2))
